def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--zip", "--zip-path", dest="zip_path", required=True)
    parser.add_argument("--version")
    args = parser.parse_args()
    version = args.version or _infer_version(Path(args.zip_path))
    payload = audit_zip(Path(args.zip_path), version=version)
    print(json.dumps(payload, indent=2, ensure_ascii=False))


def audit_zip(
    zip_path: Path, *, version: str = "v1_12_1", write_report: bool = True
) -> dict[str, Any]:
    v_norm = normalize_version(version)
    v1_84_allowed_data = {
        "data/research/microstructure_contract_materialization/v1_84/manifest.json",
        "data/research/microstructure_contract_materialization/v1_84/schema_snapshot.json",
        "data/research/microstructure_contract_materialization/v1_84/preview_records.json",
    }
    v1_87_allowed_data = {
        "data/research/microstructure_contract_materialization/v1_87/extension_manifest.json",
        "data/research/microstructure_contract_materialization/v1_87/extension_quality_summary.json",
    }
    v1_90_allowed_data = {
        "data/research/microstructure_contract_materialization/v1_90/consolidated_manifest.json",
        "data/research/microstructure_contract_materialization/v1_90/consolidated_schema_snapshot.json",
        "data/research/microstructure_contract_materialization/v1_90/consolidated_quality_summary.json",
    }
    v1_92_allowed_data = {
        "data/research/dataset_seed/v1_92/seed_manifest.json",
        "data/research/dataset_seed/v1_92/seed_schema.json",
        "data/research/dataset_seed/v1_92/seed_preview_records.json",
        "data/research/dataset_seed/v1_92/seed_provenance.json",
        "data/research/dataset_seed/v1_92/seed_quality_audit.json",
    }
    forbidden_entries = []
    secret_hits = []
    json_finiteness_issues = []
    json_files_scanned = []
    project_state_version = None
    with zipfile.ZipFile(zip_path) as archive:
        names = archive.namelist()
        
        # Extract project state version from zip
        if "reports/PROJECT_STATE.json" in names:
            try:
                content = archive.read("reports/PROJECT_STATE.json")
                state_data = json.loads(content)
                project_state_version = state_data.get("version")
                print(f"DEBUG: Found PROJECT_STATE version: {project_state_version}")
            except Exception as e:
                print(f"DEBUG: Error reading PROJECT_STATE: {e}")
        else:
            print("DEBUG: reports/PROJECT_STATE.json NOT in names")

        for name in names:
            relative = Path(name)
            parts = set(relative.parts)
            allowed_as_v1_84_data = v_norm in {"v1_84", "v1_85", "v1_86", "v1_87", "v1_87_1", "v1_87_2", "v1_88", "v1_89", "v1_90", "v1_90_1", "v1_91", "v1_91_1", "v1_91_2", "v1_91_3", "v1_91_4", "v1_92", "v1_92_1", "v1_93", "v1_93_1", "v1_93_2", "v1_93_3", "v1_93_4", "v1_93_5", "v1_94", "v1_95", "v1_95_1", "v1_96", "v1_96_1", "v1_97", "v1_97_1", "v1_97_2", "v1_98", "v1_98_1", "v1_98_2", "v1_99"} and name in v1_84_allowed_data
            allowed_as_v1_87_data = v_norm in {"v1_87", "v1_87_1", "v1_87_2", "v1_88", "v1_89", "v1_90", "v1_90_1", "v1_91", "v1_91_1", "v1_91_2", "v1_91_3", "v1_91_4", "v1_92", "v1_92_1", "v1_93", "v1_93_1", "v1_93_2", "v1_93_3", "v1_93_4", "v1_93_5", "v1_94", "v1_95", "v1_95_1", "v1_96", "v1_96_1", "v1_97", "v1_97_1", "v1_97_2", "v1_98", "v1_98_1", "v1_98_2", "v1_99"} and name in v1_87_allowed_data
            allowed_as_v1_90_data = v_norm in {"v1_90", "v1_90_1", "v1_91", "v1_91_1", "v1_91_2", "v1_91_3", "v1_91_4", "v1_92", "v1_92_1", "v1_93", "v1_93_1", "v1_93_2", "v1_93_3", "v1_93_4", "v1_93_5", "v1_94", "v1_95", "v1_95_1", "v1_96", "v1_96_1", "v1_97", "v1_97_1", "v1_97_2", "v1_98", "v1_98_1", "v1_98_2", "v1_99"} and name in v1_90_allowed_data
            allowed_as_v1_92_data = v_norm in {"v1_92", "v1_92_1", "v1_93", "v1_93_1", "v1_93_2", "v1_93_3", "v1_93_4", "v1_93_5", "v1_94", "v1_95", "v1_95_1", "v1_96", "v1_96_1", "v1_97", "v1_97_1", "v1_97_2", "v1_98", "v1_98_1", "v1_98_2", "v1_99"} and name in v1_92_allowed_data
            allowed_as_v1_95_data = v_norm in {"v1_95", "v1_95_1", "v1_96", "v1_96_1", "v1_97", "v1_97_1", "v1_97_2", "v1_98", "v1_98_1", "v1_98_2", "v1_99"} and name in {
                "data/research/feature_preview/v1_95/feature_preview_manifest.json",
                "data/research/feature_preview/v1_95/feature_preview_schema.json",
                "data/research/feature_preview/v1_95/feature_preview_rows.json",
                "data/research/feature_preview/v1_95/feature_preview_quality_audit.json",
            }
            allowed_as_v1_97_data = v_norm in {"v1_97", "v1_97_1", "v1_97_2", "v1_98", "v1_98_1", "v1_98_2", "v1_99"} and name in {
                "data/research/label_preview/v1_97/label_preview_manifest.json",
                "data/research/label_preview/v1_97/label_preview_schema.json",
                "data/research/label_preview/v1_97/label_preview_rows.json",
                "data/research/label_preview/v1_97/label_preview_quality_audit.json",
            }
            allowed_as_v1_99_data = v_norm in {"v1_99"} and name in {
                "data/research/training_dataset_preview/v1_99/training_dataset_preview_manifest.json",
                "data/research/training_dataset_preview/v1_99/training_dataset_preview_schema.json",
                "data/research/training_dataset_preview/v1_99/training_dataset_preview_rows.json",
                "data/research/training_dataset_preview/v1_99/training_dataset_preview_split_policy.json",
                "data/research/training_dataset_preview/v1_99/training_dataset_preview_quality_audit.json",
            }
