            "reports/PROJECT_STATE.json",
            "reports/PROJECT_STATE.md",
            "reports/REPORT_INDEX.md",
            "reports/current/latest_summary.md",
            "reports/current/latest_metrics.json",
            "scripts/make_clean_zip.py",
